"use client"

import { useEffect, useState } from "react"
import { StatCard } from "@/components/stat-card"
import { useAuth } from "@/app/context/auth-context"
import { UserRole } from "@/lib/auth"
import { Users, DollarSign, Calendar, UserCheck, Building2, Car, MapPin, Clock, CheckCircle2, AlertCircle } from "lucide-react"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { dashboardService, DashboardStats } from "@/lib/services/dashboard-service"
import {
  Bar, BarChart, ResponsiveContainer, XAxis, YAxis, Tooltip,
  PieChart, Pie, Cell, Legend
} from "recharts"
import { format } from "date-fns"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { userService } from "@/lib/services/user-service"
import { ParkingStatus } from "@/components/types"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { User as UserIcon, Percent, Receipt } from "lucide-react"

import { PageHeader } from "@/components/layouts/page-header"
import { cn } from "@/lib/utils"
import { PERMISSIONS } from "@/lib/permissions"

export default function DashboardPage() {
  const { user, canAccess, hasPermission } = useAuth()
  const [stats, setStats] = useState<DashboardStats | null>(null)
  const [loading, setLoading] = useState(true)
  const [chartPeriod, setChartPeriod] = useState<"weekly" | "monthly" | "yearly">("weekly")
  const [managerFilter, setManagerFilter] = useState<string>("ALL")
  const [statusFilter, setStatusFilter] = useState<string>("ALL")
  const [managers, setManagers] = useState<any[]>([])

  useEffect(() => {
    loadStats()
  }, [user, managerFilter, statusFilter])

  useEffect(() => {
    if (user && (user.role === UserRole.SYSTEM_SUPER_ADMIN || user.role === UserRole.PARKING_SUPER_ADMIN)) {
      loadManagers()
    }
  }, [user])

  const loadManagers = async () => {
    try {
      const res = await userService.getAllUsers({
        role: UserRole.PARKING_MANAGER,
        orgId: user?.orgId && user.role !== UserRole.SYSTEM_SUPER_ADMIN ? user.orgId : undefined
      })
      const userList = res.data || res.users
      if (userList) setManagers(userList)
    } catch (err) {
      console.error("Failed to load managers", err)
    }
  }

  const loadStats = async () => {
    if (!user) return
    try {
      setLoading(true)
      const data = await dashboardService.getDashboardStats({
        managerUserId: managerFilter === "ALL" ? undefined : managerFilter,
        parkingStatus: statusFilter === "ALL" ? undefined : statusFilter
      })
      setStats(data)
    } catch (error) {
      console.error(error)
    } finally {
      setLoading(false)
    }
  }

  if (loading || !stats) {
    return <div className="p-6">Loading dashboard...</div>
  }

  // --- STAT CARDS ---
  // --- KEY performance indicators (Top Row) ---
  const topKPIs = [
    {
      icon: <Users size={24} />,
      label: "Total Customers",
      value: stats.totalParkingUsers,
      change: 0,
      description: "registered users",
      show: hasPermission(PERMISSIONS.USER_VIEW)
    },
    {
      icon: <Calendar size={24} />,
      label: "Total Bookings",
      value: stats.totalBookings,
      change: 0,
      description: "lifetime sessions",
      show: hasPermission(PERMISSIONS.DASHBOARD_TOTAL_BOOKINGS)
    },
    {
      icon: <DollarSign size={24} />,
      label: "Gross Revenue",
      value: `${stats.revenue.toLocaleString()} ETB`,
      change: 0,
      description: "gross earnings",
      show: hasPermission(PERMISSIONS.DASHBOARD_TOTAL_REVENUE)
    }
  ];

  const financialStats = [
    {
      icon: <Percent size={24} />,
      label: "Platform Commission",
      value: `${(stats.commission || 0).toLocaleString()} ETB`,
      change: 0,
      description: "system earnings",
      show: hasPermission(PERMISSIONS.REVENUE_VIEW)
    },
    {
      icon: <Receipt size={24} />,
      label: "VAT Collected",
      value: `${(stats.vat || 0).toLocaleString()} ETB`,
      change: 0,
      description: "tax liability",
      show: hasPermission(PERMISSIONS.REVENUE_VIEW)
    }
  ];

  const operationalStats = [
    {
      icon: <Building2 size={24} />,
      label: "Total Capacity",
      value: stats.totalCapacity || 0,
      change: 0,
      description: "total parking spots",
      show: hasPermission(PERMISSIONS.PARKING_VIEW)
    },
    {
      icon: <CheckCircle2 size={24} />,
      label: "Available Now",
      value: stats.totalAvailableSpots || 0,
      change: 0,
      description: "free spots left",
      show: hasPermission(PERMISSIONS.PARKING_VIEW)
    },
    {
      icon: <Clock size={24} />,
      label: "Occupied",
      value: stats.activeBookings || 0,
      change: 0,
      description: "active sessions",
      show: hasPermission(PERMISSIONS.DASHBOARD_TOTAL_BOOKINGS)
    },
    {
      icon: <AlertCircle size={24} />,
      label: "Pending Payment",
      value: stats.pendingBookings || 0,
      change: 0,
      description: "unconfirmed / waiting",
      show: hasPermission(PERMISSIONS.DASHBOARD_TOTAL_BOOKINGS)
    }
  ];

  const managementStats = [
    {
      icon: <MapPin size={24} />,
      label: "Total Parkings",
      value: stats.totalParkings,
      change: 0,
      description: "registered facilities",
      show: hasPermission(PERMISSIONS.PARKING_VIEW)
    },
    {
      icon: <Car size={24} />,
      label: "Active Facilities",
      value: stats.activeParkings,
      change: 0,
      description: "online right now",
      show: hasPermission(PERMISSIONS.PARKING_VIEW)
    },
    {
      icon: <UserCheck size={24} />,
      label: "System Staff",
      value: stats.totalSystemAdmins,
      change: 0,
      description: "platform admins",
      show: user?.role === UserRole.SYSTEM_SUPER_ADMIN || user?.role === UserRole.SYSTEM_ADMIN
    },
    {
      icon: <Building2 size={24} />,
      label: "Parking Staff",
      value: stats.totalParkingStaff,
      change: 0,
      description: "Managers & Admins",
      show: hasPermission(PERMISSIONS.USER_VIEW)
    }
  ];

  // --- CHART DATA ---
  const currentChartData = stats.trends[chartPeriod];
  const paymentStats = (stats.paymentStats || [])
    .filter((p: any) => p.name === 'INCASH' || p.name === 'TRANSFER' || p.name === 'TELEBIRR')
    .map((p: any) => ({
      name: p.name === 'INCASH' ? 'Cash' : p.name === 'TELEBIRR' ? 'Telebirr' : 'Transfer',
      value: p.value
    }));

  return (
    <div className="p-4 sm:p-6 space-y-8">
      <PageHeader
        title="Dashboard"
        description={canAccess([UserRole.SYSTEM_SUPER_ADMIN]) ? "Global System Overview" : "Parking Analytics Overview"}
      >
        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 w-full sm:w-auto">
          {(user?.role === UserRole.SYSTEM_SUPER_ADMIN || user?.role === UserRole.PARKING_SUPER_ADMIN) && managers.length > 0 && (
            <div className="flex items-center gap-3 w-full sm:w-auto">
              <span className="text-xs font-bold text-slate-500 hidden lg:inline uppercase tracking-widest">Manager:</span>
              <Select value={managerFilter} onValueChange={setManagerFilter}>
                <SelectTrigger className="w-full sm:w-[180px] h-11 rounded-xl border-slate-200 bg-white shadow-sm">
                  <div className="flex items-center gap-2 truncate">
                    <UserIcon className="h-4 w-4 text-slate-400 shrink-0" />
                    <SelectValue placeholder="All Managers" />
                  </div>
                </SelectTrigger>
                <SelectContent className="rounded-xl">
                  <SelectItem value="ALL">All Managers</SelectItem>
                  {managers.map((m) => (
                    <SelectItem key={m.id} value={m.id}>
                      {m.fullName}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {(user?.role === UserRole.SYSTEM_SUPER_ADMIN || user?.role === UserRole.SYSTEM_ADMIN) && (
            <div className="flex items-center gap-3 w-full sm:w-auto">
              <span className="text-xs font-bold text-slate-500 hidden lg:inline uppercase tracking-widest">Status:</span>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-full sm:w-[160px] h-11 rounded-xl border-slate-200 bg-white shadow-sm">
                  <div className="flex items-center gap-2 truncate">
                    <SelectValue placeholder="All Status" />
                  </div>
                </SelectTrigger>
                <SelectContent className="rounded-xl">
                  <SelectItem value="ALL">All Status</SelectItem>
                  <SelectItem value={ParkingStatus.ACTIVE}>Active</SelectItem>
                  <SelectItem value={ParkingStatus.PENDING}>Pending</SelectItem>
                  <SelectItem value={ParkingStatus.DISABLED}>Disabled</SelectItem>
                  <SelectItem value={ParkingStatus.UNDER_MAINTENANCE}>Maintenance</SelectItem>
                </SelectContent>
              </Select>
            </div>
          )}
        </div>
      </PageHeader>

      {/* 1. METRICS SECTIONS */}
      <div className="space-y-8">
        {/* Top Key Indicators */}
        {topKPIs.some(s => s.show) && (
          <div className="space-y-4">
            <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
              <span className="w-8 h-[2px] bg-primary/20 rounded-full" />
              Performance Overview
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {topKPIs.filter(s => s.show).map((stat, index) => (
                <StatCard key={index} {...stat} />
              ))}
            </div>
          </div>
        )}

        {/* Financial & Operational Row */}
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
          {financialStats.some(s => s.show) && (
            <div className="space-y-4">
              <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <span className="w-8 h-[2px] bg-primary/20 rounded-full" />
                Financial Records
              </h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                {financialStats.filter(s => s.show).map((stat, index) => (
                  <StatCard key={index} {...stat} />
                ))}
              </div>
            </div>
          )}

          {operationalStats.some(s => s.show) && (
            <div className="space-y-4">
              <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <span className="w-8 h-[2px] bg-primary/20 rounded-full" />
                Live Availability
              </h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-6">
                {operationalStats.filter(s => s.show).map((stat, index) => (
                  <StatCard key={index} {...stat} />
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Management & Resources */}
        {managementStats.some(s => s.show) && (
          <div className="space-y-4">
            <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
              <span className="w-8 h-[2px] bg-primary/20 rounded-full" />
              System Resources
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
              {managementStats.filter(s => s.show).map((stat, index) => (
                <StatCard key={index} {...stat} />
              ))}
            </div>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-7 gap-6">

        {/* 3. PAYMENT METHOD PIE CHART */}
        {hasPermission(PERMISSIONS.REVENUE_VIEW) && (
          <Card className="col-span-1 lg:col-span-3 min-h-[400px] border-0 bg-white/40 backdrop-blur-md shadow-[0_8px_30px_rgb(0,0,0,0.04)] rounded-3xl ring-1 ring-slate-200/50">
            <CardHeader>
              <CardTitle>Payment Methods</CardTitle>
              <CardDescription>Distribution by transaction volume</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={paymentStats}
                      cx="50%"
                      cy="50%"
                      innerRadius={80}
                      outerRadius={100}
                      paddingAngle={5}
                      dataKey="value"
                      stroke="hsl(var(--background))"
                      strokeWidth={2}
                    >
                      {paymentStats?.map((entry: any, index: number) => (
                        <Cell
                          key={`cell-${index}`}
                          fill={index === 0 ? "var(--primary)" : "#6366f1"}
                          fillOpacity={1}
                        />
                      ))}
                    </Pie>
                    <Tooltip
                      contentStyle={{
                        borderRadius: '8px',
                        border: '1px solid hsl(var(--border))',
                        backgroundColor: 'hsl(var(--background))'
                      }}
                    />
                    <Legend verticalAlign="bottom" height={36} iconType="circle" />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </CardContent>
          </Card>
        )}

        {/* 2. MAIN TRENDS CHART */}
        <Card className={cn(
          "col-span-1 min-h-[400px] border-0 bg-white/40 backdrop-blur-md shadow-[0_8px_30px_rgb(0,0,0,0.04)] rounded-3xl ring-1 ring-slate-200/50",
          hasPermission(PERMISSIONS.REVENUE_VIEW) ? "lg:col-span-4" : "lg:col-span-7"
        )}>
          <CardHeader className="flex flex-col sm:flex-row items-start sm:items-center justify-between pb-2">
            <div>
              <CardTitle>Booking Trends</CardTitle>
              <CardDescription>Revenue volume over time</CardDescription>
            </div>
            <Tabs defaultValue="weekly" value={chartPeriod} onValueChange={(v) => setChartPeriod(v as any)} className="mt-2 sm:mt-0">
              <TabsList>
                {hasPermission(PERMISSIONS.DASHBOARD_DAILY_STATS) && <TabsTrigger value="weekly">Weekly</TabsTrigger>}
                {hasPermission(PERMISSIONS.DASHBOARD_MONTHLY_STATS) && <TabsTrigger value="monthly">Monthly</TabsTrigger>}
                {hasPermission(PERMISSIONS.DASHBOARD_YEARLY_STATS) && <TabsTrigger value="yearly">Yearly</TabsTrigger>}
              </TabsList>
            </Tabs>
          </CardHeader>
          <CardContent>
            <div className="h-[300px] w-full mt-4">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={currentChartData}>
                  <XAxis
                    dataKey="name"
                    stroke="#888888"
                    fontSize={12}
                    tickLine={false}
                    axisLine={false}
                  />
                  <YAxis
                    stroke="#888888"
                    fontSize={12}
                    tickLine={false}
                    axisLine={false}
                    tickFormatter={(value) => `${value}`}
                  />
                  <Tooltip
                    cursor={{ fill: 'var(--muted)', opacity: 0.2 }}
                    contentStyle={{
                      borderRadius: '8px',
                      border: '1px solid hsl(var(--border))',
                      boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                      backgroundColor: 'hsl(var(--background))'
                    }}
                  />
                  <Bar
                    dataKey="total"
                    fill="var(--primary)"
                    radius={[4, 4, 0, 0]}
                    name="Revenue (ETB)"
                    barSize={40}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
